import{_ as t,o as e,c as i,a5 as s}from"./chunks/framework.a5no_H3L.js";const b=JSON.parse('{"title":"Federation 与 Shovel","description":"Federation 和 Shovel 是 RabbitMQ 的跨集群消息传递方案。它们解决的是消息要跨集群流动的问题，但这个流动是异步的、有损耗边界的，和集群内同步复制完全不同。","frontmatter":{},"headers":[],"relativePath":"rabbitmq/07-clustering/chapter-05-federation.md","filePath":"rabbitmq/07-clustering/chapter-05-federation.md"}'),n={name:"rabbitmq/07-clustering/chapter-05-federation.md"};function r(l,a,d,h,c,p){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="federation-与-shovel" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">Federation 与 Shovel <a class="header-anchor" href="#federation-与-shovel" aria-label="Permalink to &quot;Federation 与 Shovel&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><p data-src-line="3" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">Federation 和 Shovel 是 RabbitMQ 的跨集群消息传递方案。它们解决的是消息要跨集群流动的问题，但这个流动是异步的、有损耗边界的，和集群内同步复制完全不同。</p></blockquote><h2 id="_1-federation" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">1. Federation <a class="header-anchor" href="#_1-federation" aria-label="Permalink to &quot;1. Federation&quot;">​</a></h2><p data-src-line="7" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">Federation 在两个集群之间建立联邦关系，上游的消息自动流向下游。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上游集群 (Beijing)              下游集群 (Shanghai)</span></span>
<span class="line"><span>  Exchange A ──Federation Link──▶ Exchange A&#39;</span></span>
<span class="line"><span>  Queue B    ──Federation Link──▶ Queue B&#39;</span></span></code></pre></div><h3 id="link-的原理" tabindex="-1" data-src-line="15" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">Link 的原理 <a class="header-anchor" href="#link-的原理" aria-label="Permalink to &quot;Link 的原理&quot;">​</a></h3><p data-src-line="17" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">Federation 由下游向上游主动建立连接，流量方向是从上游拉到下游，不是上游推下来。上游把下游当成一个普通消费者，走标准 AMQP 协议。下游集群上出现一个看起来像本地资源的影子，但影子背后是什么，取决于联邦的资源类型。</p><p data-src-line="19" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">对 Federated Exchange，下游交换机从上游交换机复制符合其绑定关系的消息流，再按下游的路由规则投递。Federation 会把下游的绑定关系传播到上游，因此不是把上游交换机的全部消息无条件复制过来。</p><p data-src-line="21" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">对 Federated Queue，下游队列只在本地有消费需求、且上游有可转移消息时，才从上游队列取消息。它更接近跨节点的按需转移，而不是交换机联邦式的整片复制。</p><p data-src-line="23" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">对下游消费者来说，它消费的是一个普通队列，感知不到消息其实来自另一个集群。</p><h3 id="配置" tabindex="-1" data-src-line="25" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmq-plugins</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rabbitmq_federation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmq-plugins</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rabbitmq_federation_management</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 添加上游</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set_parameter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> federation-upstream</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-upstream</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;{&quot;uri&quot;:&quot;amqp://user:***@upstream-host:5672&quot;,&quot;prefetch-count&quot;:1000}&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 设置策略</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set_policy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> federate-me</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;^order</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;{&quot;federation-upstream-set&quot;:&quot;all&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply-to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exchanges</span></span></code></pre></div><h3 id="确认语义" tabindex="-1" data-src-line="40" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">确认语义 <a class="header-anchor" href="#确认语义" aria-label="Permalink to &quot;确认语义&quot;">​</a></h3><p data-src-line="42" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">Federation 通过 AMQP 链路异步转发消息，上游、链路、下游的确认分属不同层次。链路如何向上游确认，由上游的 ack-mode 决定，默认是 on-confirm：消息在下游确认发布成功后，才向上游确认。这个默认值在网络错误和 Broker 故障场景下不丢消息，是三档中最慢的。它只覆盖跨链路传递这一段，不替代持久化与业务幂等。</p><p data-src-line="44" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">另两档是 on-publish 和 no-ack：on-publish 在下游发布后、尚未获得下游发布确认时就向上游确认，下游 Broker 在确认前故障会丢消息；no-ack 不做确认，最快但最容易丢。</p><p data-src-line="46" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">无论哪一档，Federation 都不能提供跨集群的恰好一次投递或强一致。下游消费者 ack 只表示本地消费完成，与链路向上游的确认是两回事。所以 Federation 适合追求最终一致、可容忍重复投递的场景，不适合要求强一致的场景。</p><h3 id="适用场景" tabindex="-1" data-src-line="48" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><ul data-src-line="50" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><li data-src-line="50" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">跨数据中心消息同步</li><li data-src-line="51" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">多环境消息桥接</li><li data-src-line="52" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">云上云下消息互通</li></ul><h2 id="_2-shovel" tabindex="-1" data-src-line="54" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">2. Shovel <a class="header-anchor" href="#_2-shovel" aria-label="Permalink to &quot;2. Shovel&quot;">​</a></h2><p data-src-line="56" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">Shovel 是一个持续运行的消息转移任务：从源端消费消息，再发布到目标端。源端和目标端可以属于不同 RabbitMQ 集群，也可以是支持相应 AMQP 协议的其他消息系统，两端可以使用不同协议。它不依赖联邦交换机或联邦队列的语义，也不会自动复制上游的拓扑与绑定关系，目标端的队列、交换机是否需要预先声明，取决于配置与协议能力。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Source Broker ──Shovel──▶ Destination Broker</span></span>
<span class="line"><span>(RabbitMQ)                (RabbitMQ / 其他 AMQP)</span></span></code></pre></div><h3 id="配置-1" tabindex="-1" data-src-line="63" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">配置 <a class="header-anchor" href="#配置-1" aria-label="Permalink to &quot;配置&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmq-plugins</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rabbitmq_shovel</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmq-plugins</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rabbitmq_shovel_management</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set_parameter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shovel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-shovel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;src-protocol&quot;: &quot;amqp091&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;src-uri&quot;: &quot;amqp://source-host:5672&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;src-queue&quot;: &quot;order.queue&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;dest-protocol&quot;: &quot;amqp091&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;dest-uri&quot;: &quot;amqp://dest-host:5672&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;dest-queue&quot;: &quot;order.queue&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p data-src-line="80" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">这是动态 Shovel，通过运行时参数声明，官方在多数场景推荐优先使用。它的确认模式默认 on-confirm，在目标端确认发布后才向源端确认。</p><h2 id="_3-federation-vs-shovel" tabindex="-1" data-src-line="82" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">3. Federation vs Shovel <a class="header-anchor" href="#_3-federation-vs-shovel" aria-label="Permalink to &quot;3. Federation vs Shovel&quot;">​</a></h2><table tabindex="0"><thead data-src-line="84" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><tr data-src-line="84" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><th style="text-align:left;">维度</th><th style="text-align:left;">Federation</th><th style="text-align:left;">Shovel</th></tr></thead><tbody data-src-line="86" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><tr data-src-line="86" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><td style="text-align:left;">粒度</td><td style="text-align:left;">联邦资源（交换机/队列）</td><td style="text-align:left;">消息转移任务</td></tr><tr data-src-line="87" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><td style="text-align:left;">配置</td><td style="text-align:left;">策略驱动</td><td style="text-align:left;">参数驱动</td></tr><tr data-src-line="88" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><td style="text-align:left;">协议</td><td style="text-align:left;">AMQP 0-9-1</td><td style="text-align:left;">AMQP 0-9-1、AMQP 1.0</td></tr><tr data-src-line="89" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><td style="text-align:left;">灵活性</td><td style="text-align:left;">较低</td><td style="text-align:left;">较高</td></tr><tr data-src-line="90" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><td style="text-align:left;">适用场景</td><td style="text-align:left;">集群间消息流分发、按需转移</td><td style="text-align:left;">消息迁移、跨 Broker 转发、跨协议转移</td></tr></tbody></table><p data-src-line="92" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">选型看的是需要的消息流转语义：要让远端交换机接收上游符合绑定关系的消息流，或让消费端在本地无可用消息时从上游队列取消息，用 Federation；要从指定源端持续消费消息并重新发布到另一个 Broker，用 Shovel。两者都需要单独评估确认、重复投递、拓扑管理和故障恢复行为，不能只凭「复制」或「搬运」两个词判断可靠性。</p><h2 id="_4-消息防环" tabindex="-1" data-src-line="94" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">4. 消息防环 <a class="header-anchor" href="#_4-消息防环" aria-label="Permalink to &quot;4. 消息防环&quot;">​</a></h2><p data-src-line="96" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">跨集群用 Federation 做双向或多向同步时，最怕的是消息在两个集群之间来回转发，形成环路，同一条消息被反复复制。</p><p data-src-line="98" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">对 Federated Exchange，防环靠 max-hops 参数，它限制消息经过 Federation Link 的次数，默认值为 1，达到上限的消息不再继续经联邦链路转发。这一机制由 RabbitMQ 自动维护，通常不需要用户自行给业务消息添加标记。需要区分的是，Federated Queue 没有同等的显式环路限制，多个联邦队列组成复杂拓扑时，不能指望交换机的 max-hops 规则来兜底。</p><p data-src-line="100" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">所以设计双向或多向拓扑时，应明确消息来源与转发方向，优先采用容易验证的拓扑，避免让同一条业务消息经过不必要的多条联邦路径。</p><h2 id="_5-注意事项" tabindex="-1" data-src-line="102" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">5. 注意事项 <a class="header-anchor" href="#_5-注意事项" aria-label="Permalink to &quot;5. 注意事项&quot;">​</a></h2><ul data-src-line="104" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md"><li data-src-line="104" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">Federation 与 Shovel 都是异步的，不保证实时同步</li><li data-src-line="105" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">消息可能被重复投递，网络中断恢复后会有重发</li><li data-src-line="106" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">确认语义取决于 ack-mode：默认 on-confirm 在下游确认后才向上游确认，on-publish 和 no-ack 存在不同程度的消息丢失风险</li><li data-src-line="107" data-src-file="rabbitmq/07-clustering/chapter-05-federation.md">跨集群延迟、带宽、确认等待时间和消息大小共同影响吞吐，需通过压测确定实际容量，而非单凭网络距离推断</li></ul>`,33)])])}const k=t(n,[["render",r]]);export{b as __pageData,k as default};
